import json, re, html
from pathlib import Path
S=json.loads(Path('source.json').read_text())
R=json.loads(Path('reference-targets.json').read_text())
A=[]
for s in S:
    a={k:s[k] for k in ('code_id','source_id','source_sha256','number')}
    a.update(proposed_xml=None,reason='',review_notes='',status='retained_unchanged',classification='retained_necessary')
    a['substantive_impact']={'version':1,'classification':'retained_necessary','assessment':'','scope_limitations':'','new_burdens_review':'Aucune charge nouvelle n’est identifiée : le texte source est maintenu intégralement, sans nouvelle donnée, déclaration, condition ou échéance. Aucun solde global des codes n’est chiffré.','effects':[]}
    a['reference_checks']=[]
    A.append(a)

def retain(i,reason,notes,assessment,limits):
    a=A[i];a['reason']=reason;a['review_notes']=notes
    a['substantive_impact']['assessment']=assessment
    a['substantive_impact']['scope_limitations']=limits

def rewrite(i,xml,reason,notes,classification,assessment,limits,burdens,removed=None):
    a=A[i];a.update(proposed_xml=xml.strip(),reason=reason,review_notes=notes,status='rewrite_draft')
    a.pop('classification',None)
    a['substantive_impact'].update(classification=classification,assessment=assessment,scope_limitations=limits,new_burdens_review=burdens)
    if removed:
        a.update(change_type='normative_reduction',reform_policy_id='editorial_direction_2026_10_19',removed_provisions=removed)

def effect(i,kind,measure,description,before,after,unit,population,conditions,replacement,source,proposed):
    A[i]['substantive_impact']['effects'].append(dict(kind=kind,measure_id=measure,description=description,before=before,after=after,unit=unit,affected_population=population,conditions_and_transition=conditions,replacement_or_new_burdens=replacement,source_quote=source,proposed_quote=proposed))

retain(0,
"Maintien intégral d’un avantage familial : un trimestre au titre de L351-4, L351-4-1 ou L351-5 suffit à abaisser d’un an l’âge de la surcote, lorsque l’âge de référence atteint au moins soixante-trois ans. Le décret interrégimes protège les bonifications équivalentes. L’examen n’identifie ici ni prélèvement accessoire ni autorisation individuelle à retirer ; supprimer le texte retirerait l’avantage aux futurs parents éligibles.",
"Le renvoi au premier alinéa de L351-1-2 vise l’âge de la surcote, pas l’âge de liquidation de toute pension. Le second alinéa évoque indirectement la majoration de pension du premier : rédaction elliptique préexistante, sans nouveau taux. L351-5 reçoit dans ce lot une coordination du congé parental, sans fermeture de son avantage. Note source : application des modifications visées au 1er janvier 2025 ; ce n’est pas la date de la réforme projetée.",
"L’abaissement d’un an et la prise en compte interrégimes sont conservés pour les situations futures comme pour les droits antérieurs. Aucune baisse de cotisation ou simplification nouvelle n’est revendiquée.",
"Le taux de surcote et les modalités interrégimes relèvent d’autres textes ; aucun élargissement à tous les assurés ni transfert automatique vers la capitalisation n’est établi.")
retain(1,
"Maintien intégral du départ anticipé et de la majoration de pension des assurés handicapés : incapacité permanente d’au moins 50 %, durée cotisée pendant le handicap et totalisation des régimes. Ces conditions établissent le champ d’une prestation favorable, non un agrément professionnel ou une déclaration doublonnée. Leur suppression ne serait pas une suppression de prélèvement ; les futurs assurés remplissant les conditions gardent l’avantage.",
"Le premier alinéa de L351-1 est bien l’ouverture selon l’âge ; son deuxième traite du taux. La majoration du deuxième alinéa de L351-1-3 demeure additionnelle au minimum de L351-10. Ne pas lui appliquer le seuil d’un an ni le plafond de six mois de l’indemnité de rupture. Note source : pensions prenant effet à compter du 1er septembre 2023 ; seuil de 50 % conservé.",
"Le texte entier conserve une compensation du handicap et n’ajoute aucune formalité. Le renvoi au décret fixe la durée cotisée et le calcul de la majoration, sans baisse nouvelle de charges démontrée.",
"Les paramètres réglementaires et l’évaluation médicale ne sont pas recalculés ; les droits futurs de solidarité ne sont pas supprimés par le projet de capitalisation.")

# L351-1-4 : suppression d'un circuit obligatoire, maintien des critères et garanties.
p2=re.findall(r'<p>(.*?)</p>',S[2]['source_xml'],re.S)
oldcommission=p2[6]
assert oldcommission.startswith('Une commission pluridisciplinaire')
newcommission="L'organisme débiteur de la pension de retraite apprécie les conditions prévues aux 2° et 3° et les modes de preuve apportés par l'assuré, sans saisine ni avis obligatoire d'une commission pluridisciplinaire. L'assuré conserve le droit d'être entendu et de se faire assister par une personne de son choix. Les informations médicales restent couvertes par le secret professionnel. La suppression de ce circuit ne modifie ni les règles de reconnaissance de l'incapacité permanente professionnelle ni les voies de recours contre la décision de l'organisme."
p2[6]=newcommission
p2[7]=p2[7].replace(" L'avis de commission pluridisciplinaire susmentionnée n'est dans ce cas pas requis.","")
p2.append("La suppression de la saisine et de l'avis obligatoires s'applique aux demandes qui n'ont pas fait l'objet d'une décision définitive à la date d'entrée en vigueur de la loi portant la présente rédaction, y compris aux demandes en cours d'examen. Aucun nouveau dossier n'est exigé du seul fait de cette suppression. Les avis favorables déjà rendus restent opposables à l'organisme débiteur de la pension. Les pensions liquidées, les créances acquises et les recours relatifs aux décisions antérieures sont préservés.")
rewrite(2,'\n'.join('<p>'+p+'</p>' for p in p2),
"Réforme de fond : suppression de la validation obligatoire par une commission pluridisciplinaire pour le départ anticipé au titre du III. La caisse qui liquide la pension statue directement sur les mêmes critères d’exposition et de causalité ; aucune déclaration ni aucun agrément de remplacement n’est créé. Le droit d’être entendu, l’assistance et le secret médical, déjà prévus dans le dispositif réglementaire, restent protégés. À droit constant, maintien du départ à soixante ans du I, du taux plein du II, de l’abaissement de deux ans du III, des taux réglementaires et de la dispense des conditions 2° et 3° pour les maladies déjà désignées.",
"D351-1-9 à D351-1-12 ont été lus dans le corpus : 20 % au I, 10 % au III et dix-sept ans d’exposition ne sont pas modifiés. D351-1-11 doit perdre la constitution et le fonctionnement obligatoires de la commission ; D351-1-12 doit être coordonné au dossier traité par la caisse, en conservant les preuves utiles et sans nouvelle production des pièces déjà légalement disponibles. Ces règlements ne sont pas modifiés dans ce lot. Le renvoi exact de la source est L434-1 A, deuxième alinéa ; cette cible nouvelle n’est pas fournie, ni retrouvée sous ce numéro dans le corpus consulté. Les cibles L434-1 et L434-2 fournies ne lui sont pas substituées. La source et ses notes combinent effet immédiat et application aux pensions à la date fixée par la législation 2025 : ces transitions médicales restent distinctes de la suppression procédurale. La dispense existante des 2° et 3° reste intégrale pour les maladies de la liste ; leur régime n’est pas durci. Coût et délais réels du circuit supprimé non chiffrés.",
'material_reduction',
"La source entière impose un avis conforme supplémentaire à la caisse. La proposition retire ce passage obligatoire et sa validation séparée, tout en conservant les critères de fond et la dispense favorable pour certaines maladies ; aucune seconde taxe supprimée n’est comptée.",
"Les droits à pension et les taux d’incapacité restent identiques. Les règlements du circuit doivent être coordonnés ; la durée réellement gagnée et le solde de coûts public/privé ne sont pas établis.",
"Aucune charge nouvelle n’est identifiée : la caisse conserve sa décision de liquidation et apprécie les mêmes preuves sans dossier supplémentaire. Audition, assistance et secret proviennent du régime existant de D351-1-11, sans registre ni déclaration de remplacement.",
["Saisine obligatoire et avis conforme de la commission pluridisciplinaire validant les modes de preuve et le lien entre incapacité et exposition avant la décision de pension.","Organisation réglementaire d’un circuit distinct de composition, de fonctionnement et de ressort de cette commission ; sa dispense limitée devient sans objet puisque le circuit obligatoire est retiré pour tous."])
effect(2,'obligation_removed','retraite-incapacite-fin-commission-obligatoire',
"Retrait de l’étape obligatoire de validation par une commission avant liquidation.",
"Pour les demandes relevant du III hors dispense, validation des modes de preuve et du lien d’exposition par une commission dont l’avis lie la caisse.",
"Décision par la caisse sans saisine ni avis obligatoires d’une commission, avec les mêmes conditions de fond et les mêmes exceptions.",'legal_duty',
"Assurés demandant le départ anticipé pour incapacité permanente professionnelle dans le champ du III.",
"Demandes non définitivement décidées à l’entrée en vigueur, y compris en cours ; avis favorables existants, pensions liquidées et recours préservés.",
"Aucun dossier de remplacement ; appréciation déjà nécessaire à la liquidation et garanties existantes conservées.",oldcommission,newcommission)

retain(3,
"Maintien intégral de l’abaissement d’âge pour inaptitude ou incapacité permanente. Le renvoi à L351-7 conserve le constat médical protecteur, distinct d’un licenciement pour inaptitude ; le décret fixe le champ et l’âge favorable. Aucun prélèvement, délai minimal de demande ni pièce répétée n’est institué dans cet article. Retirer cette habilitation fermerait un départ anticipé utile, y compris aux futurs assurés éligibles.",
"Le renvoi au premier alinéa de L351-1 porte sur l’âge d’ouverture. Le seuil médical fixé par décret n’est pas remplacé par celui d’une indemnité de rupture. L351-8 2° conserve le taux plein ; L351-7-1 A et L821-1 utilisent cet âge pour l’AAH. Note source : pensions prenant effet dès le 1er septembre 2023, sans nouvelle date de réforme inventée.",
"L’avantage d’âge est maintenu dans son champ propre ; aucune simplification ni baisse de prélèvement nouvelle n’est démontrée par ce maintien.",
"Le taux réglementaire d’incapacité et l’âge effectif ne sont pas changés. Les régimes d’inaptitude professionnelle de rupture du contrat restent distincts.")

oldproof="En cas de force majeure ou d'impossibilité manifeste pour l'assuré d'apporter la preuve du versement de cotisations, celle-ci peut l'être à l'aide de documents probants ou de présomptions concordantes."
newproof="Le versement des cotisations peut être établi à l'aide de documents probants ou de présomptions concordantes, sans que l'assuré ait à justifier d'un cas de force majeure ou d'une impossibilité manifeste d'en apporter la preuve."
x=S[4]['source_xml'].replace(oldproof,newproof)
assert x!=S[4]['source_xml']
x+="<p>Cette règle de preuve s'applique aux demandes et aux contestations qui n'ont pas fait l'objet d'une décision définitive à la date d'entrée en vigueur de la loi portant la présente rédaction, y compris lorsqu'elles portent sur des périodes antérieures. Elle ne remet en cause ni les périodes déjà validées ni les créances acquises.</p>"
rewrite(4,x,
"Réforme de fond ciblée : les documents probants et présomptions concordantes deviennent recevables sans devoir prouver préalablement une force majeure ou une impossibilité manifeste. La preuve du versement demeure nécessaire ; seule la condition préalable à ce mode de preuve est retirée. Le minimum annuel de cotisations, la limite de quatre trimestres des régularisations tardives sans preuve d’activité et la fiction favorable de cotisations pendant un congé formation non rémunéré sont intégralement maintenus.",
"L244-3 borne la situation de régularisation mentionnée au premier alinéa : il n’est ni abrogé ni transformé en délai d’emploi. La limite de quatre trimestres reste attachée à l’absence de documents prouvant l’activité rémunérée ; elle n’est pas élargie au cas ordinaire. R351-9, lu, conserve les seuils de validation historiques et les 150 heures pour les années postérieures à 2013 ; ces montants ne sont pas réduits ici. L’allégement dépasse un simple réemploi des données du CRPA : il supprime le préalable légal d’impossibilité à l’administration de preuves alternatives. Il ne dispense pas de contrôler leur caractère probant et ne constitue pas une garantie de droits supplémentaires sur les cotisations transférées vers la capitalisation.",
'material_reduction',
"Par rapport à la source entière, une condition probatoire autonome disparaît : les preuves alternatives ne sont plus réservées aux seules situations de force majeure ou d’impossibilité manifeste. Ni cotisation principale ni nombre maximal de trimestres n’est abaissé.",
"Le gain dépend des carrières dont la preuve est incomplète ; aucun nombre de bénéficiaires ni coût de droits nouveaux n’est calculé. Les autres conditions de validation et de recours demeurent.",
"Aucune charge nouvelle n’est identifiée : les mêmes documents et présomptions peuvent établir le versement, sans attestation d’impossibilité ni démarche de remplacement. Le contrôle du versement reste celui déjà nécessaire.",
["Condition de force majeure ou d’impossibilité manifeste que l’assuré devait établir pour accéder à la preuve du versement par documents probants ou présomptions concordantes."])
effect(4,'obligation_removed','retraite-preuve-cotisations-sans-impossibilite',
"Suppression du préalable exceptionnel pour faire valoir des preuves alternatives du versement.",
"Documents probants ou présomptions concordantes admis seulement en cas de force majeure ou d’impossibilité manifeste pour l’assuré d’apporter la preuve du versement.",
"Ces mêmes preuves sont admises sans justification préalable de force majeure ou d’impossibilité ; versement minimum et limite spéciale de quatre trimestres conservés.",'legal_duty',
"Assurés sollicitant la prise en compte de périodes d’assurance et disposant de documents probants ou de présomptions concordantes.",
"Demandes et contestations non définitivement décidées à l’entrée en vigueur, même sur des périodes anciennes ; validations et créances acquises préservées.",
"Aucune déclaration ou attestation nouvelle ; le versement reste à établir.",oldproof,newproof)
A[4]['benefit_review']="La preuve de substitution par documents probants ou présomptions concordantes est conservée et élargie à l’ensemble des assurés sans préalable de force majeure. La validation dérogatoire du congé formation non rémunéré reste entière : retenues réputées égales à celles de la période antérieure de même durée rémunérée. La régularisation tardive demeure possible dans son champ, avec sa limite de quatre trimestres en l’absence de preuve d’activité. Le minimum annuel est une condition de validation, non une exonération supprimée ; aucune de ces facultés n’est réservée aux dossiers déjà ouverts."

retain(5,
"Maintien des neuf catégories de périodes assimilées : prestations de santé et de naissance, chômage et accompagnement, chômage non indemnisé, service national et guerre, détention provisoire, sportifs et stages. Ce sont des droits de solidarité sans versement personnel correspondant, non des charges accessoires à abolir. Les justifications historiques du 5° servent à établir des périodes dépourvues de traces de cotisations ; l’article n’impose pas une nouvelle déclaration périodique. Aucun avantage futur lié à un revenu de remplacement n’est fermé par la fin des nouveaux CDD.",
"Source entière et notes lues : état ABROGE_DIFF, valid_until au 1er novembre 2026, à distinguer d’une abrogation de l’ensemble des droits assimilés. La rédaction successeur n’est pas jointe dans ce lot ; la concordance de version reste à contrôler avant consolidation, sans considérer ces droits comme supprimés. Incohérence textuelle préexistante signalée au 1° : la seconde occurrence « ou du congé supplémentaire de naissance » se rattache à une rente prenant effet avant le 1er juillet 1930, alors que les notes limitent le nouveau congé aux naissances/adoptions de 2026 et assimilées. Aucune suppression silencieuse de cette occurrence n’est pratiquée. R351-12, lu entier, distingue bien les 58 jours de congé supplémentaire et les rentes AT. L1233-68 8° continue de définir l’allocation du CSP ; sa durée et ses périodes de travail ne deviennent pas un nouveau CDD. L1233-72, L5123-6 et les anciens stages conservent leurs champs distincts.",
"Les périodes assimilées restent toutes maintenues depuis la source officielle entière. La réorganisation du CSP et du contrat de travail ne retire pas les périodes indemnisées ; aucun allégement de prélèvement n’est compté.",
"La rédaction annoncée après le 1er novembre 2026 et la duplication du 1° constituent des réserves de consolidation documentaire. Les barèmes de validation et les conditions des revenus de remplacement ne sont pas modifiés.")
retain(6,
"Maintien de l’exclusion limitée du seul 1° de L351-3 pour les personnes détachées qui relèvent d’un accord international et ne sont pas affiliées à une retraite française obligatoire. Cette règle coordonne le régime compétent et évite une attribution française sans affiliation ; elle ne crée ni cotisation nouvelle ni attestation supplémentaire. Son retrait ne simplifierait pas les obligations et pourrait perturber la coordination internationale.",
"Les deux conditions sont cumulatives : accord international de sécurité sociale et absence d’affiliation française obligatoire. Ne pas étendre l’exclusion aux autres périodes de L351-3, aux salariés détachés affiliés en France ni aux majorations familiales. La réserve de version de L351-3 et l’anomalie de son 1° sont signalées dans son objet, sans réécrire ici un accord international.",
"Le champ de coordination internationale du 1° de L351-3 reste identique ; aucun transfert de financeur ni avantage supplémentaire n’est annoncé.",
"Les accords internationaux eux-mêmes ne sont pas dans le lot. Le type de contrat privé et le calcul de son indemnité ordinaire ne déterminent pas l’affiliation visée.")

p7=re.findall(r'<p>(.*?)</p>',S[7]['source_xml'],re.S)
oldVII=next(p for p in p7 if p.startswith('VII.-'))
newVII="VII.-L'attribution de la majoration prévue au II n'est subordonnée à aucune durée minimale d'assurance de l'un ou l'autre des parents."
p7[p7.index(oldVII)]=newVII
oldX=next(p for p in p7 if p.startswith('X.-'))
p7[p7.index(oldX)]="X.-(Abrogé)."
p7.append("La suppression de la condition de durée minimale d'assurance prévue au VII s'applique aux pensions prenant effet à compter de l'entrée en vigueur de la loi portant la présente rédaction, y compris aux demandes en cours. Les pensions prenant effet avant cette date restent soumises aux règles qui leur étaient applicables. Les trimestres déjà attribués et les droits acquis sont conservés. L'abrogation du X n'impose aucune reconstitution des rapports antérieurs.")
rewrite(7,'\n'.join('<p>'+p+'</p>' for p in p7),
"Réforme de fond : suppression du préalable de deux ans d’assurance de chacun des parents à la majoration d’éducation du II. Cette condition pouvait priver un parent éligible de ses trimestres en raison de la carrière de l’autre ; sa suppression élargit l’avantage sans imposer une cotisation ni une démarche de remplacement. Le X, relatif à deux rapports avant 2015, est retiré comme obligation épuisée, sans revendiquer un gain annuel actuel. Tous les autres paragraphes sont maintenus littéralement : quatre trimestres de maternité, d’éducation et d’adoption, choix et répartition, minimum maternel de deux trimestres, décès, parents de même sexe, substitutions judiciaires, résidence, exclusions pénales, délai de deux mois et IX abrogé.",
"Les II et III gardent le délai de six mois à partir du quatrième anniversaire, le départ différé si aucun parent n’est assuré, le traitement du désaccord et les décisions implicites. Ces règles répartissent un droit entre deux titulaires et protègent leur consentement et la stabilité des liquidations ; elles ne sont pas transformées en nouvelles déclarations. L’exception du VII pour le parent ayant élevé seul l’enfant devient couverte par l’absence générale de durée minimale, sans perte pour ce parent. Le régime des parents assurés sociaux du II reste requis. L173-2-0-1, lu, conserve son plafond de quatre trimestres par parent au titre des II et III et sa coordination interrégimes : aucune multiplication de trimestres. Les dispositions réglementaires d’instruction doivent cesser d’exiger les deux ans ; l’absence de cette pièce ne peut bloquer les nouvelles pensions. Le X était déjà historiquement échu : suppression documentaire, pas économie future chiffrée. Note source : modifications applicables aux pensions prenant effet dès le 1er septembre 2026 ; la présente extension possède sa propre transition et n’antidate pas cette loi future.",
'material_reduction',
"La source officielle impose au VII une durée minimale de deux ans à chacun des parents ; la proposition supprime ce verrou pour la majoration d’éducation. Les montants, garanties de partage et protections de l’enfant demeurent. La suppression des rapports de 2015 n’est pas comptée comme un nouvel allégement annuel.",
"L’extension vise seulement les pensions prenant effet après l’entrée en vigueur et n’ouvre pas une révision rétroactive générale. Les autres conditions de L351-4, le plafond interrégimes et les exclusions judiciaires subsistent ; coût des droits supplémentaires non chiffré.",
"Aucune charge nouvelle n’est identifiée : le contrôle des deux années disparaît sans attestation ou délai de remplacement. Les options, répartitions et justificatifs utiles déjà prévus aux autres paragraphes restent seuls applicables.",
["Condition de durée d’assurance minimale de deux ans de chacun des parents dans un régime obligatoire de l’Union européenne, de l’EEE ou de Suisse pour attribuer la majoration d’éducation du II.","Obligations historiquement échues d’élaborer un rapport sur l’éducation des enfants puis un rapport d’orientation avant le 1er janvier 2015 ; aucune nouvelle périodicité ou reconstitution n’est imposée."])
effect(7,'relief_extended','retraite-education-fin-condition-deux-ans',
"Ouverture de la majoration d’éducation sans condition de durée d’assurance de chacun des parents.",
"Pour la majoration du II, chacun des parents devait justifier de deux ans auprès d’un régime obligatoire UE/EEE/Suisse, sauf parent ayant élevé seul l’enfant.",
"Aucune durée minimale d’assurance d’un parent ou de l’autre ; maintien du champ des parents assurés et des règles d’attribution, de partage et de plafond.",'legal_duty',
"Parents assurés sociaux susceptibles de recevoir les trimestres d’éducation du II, notamment lorsque la carrière de l’un est inférieure à deux ans.",
"Pensions prenant effet à compter de l’entrée en vigueur, même sur demande pendante ; pas de réouverture générale des pensions antérieures et droits acquis préservés.",
"Aucun justificatif compensatoire ni nouveau taux ; suppression d’une condition d’accès et du contrôle correspondant.",oldVII,newVII)
A[7]['benefit_review']="Sont conservés pour les familles futures : les quatre trimestres de maternité du I ; les quatre d’éducation du II et d’adoption du III, avec au moins deux pour la mère dans les cas prévus, les partages entre parents de même sexe, les attributions par défaut et les redistributions au survivant. Le IV maintient la substitution des tiers judiciairement chargés de l’enfant. Les avantages en cas de décès de l’enfant, dont les quatre trimestres du VI, restent entiers. L’exception du VII pour le parent isolé est englobée dans la suppression générale de toute durée minimale d’assurance : ce parent ne perd rien et les autres parents peuvent devenir éligibles. Les droits acquis et plafonds interrégimes restent protégés ; les exclusions judiciaires protégeant l’enfant subsistent. Le X est un rapport échu, pas une exonération ou une prestation."

retain(8,
"Maintien intégral de la majoration pour l’éducation d’un enfant handicapé : un trimestre par trente mois, plafond de huit, cumul possible avec L351-4 et alternative entre complément d’AEEH et prestation de compensation. L’article ne comporte ni agrément ni démarche périodique distincte à supprimer ; ses critères relient des droits de retraite à une charge familiale effective. Le droit reste ouvert pour les périodes futures éligibles.",
"Les deux premiers alinéas de L541-1 identifient l’AEEH et son complément ; la PCH de L245-1 CASF intervient en lieu et place du complément, non comme exigence cumulative. Les trente mois et huit trimestres ne sont ni des délais d’emploi ni une réduction de cotisation. L351-8 6° utilise cette majoration pour le taux plein à soixante-cinq ans ; ne pas fermer ce renvoi.",
"Les huit trimestres au plus et le cumul favorable avec les droits familiaux ordinaires restent identiques ; aucune nouvelle simplification ni baisse de financement n’est revendiquée.",
"Les conditions des prestations AEEH/PCH relèvent de leurs textes propres ; ce maintien ne vaut pas suppression de ces conditions ni validation automatique de chaque période.")
retain(9,
"Maintien intégral de la majoration de l’aidant d’un adulte handicapé : un trimestre par trente mois, huit au plus. Le foyer, la prise en charge permanente, le taux réglementaire et la liste familiale déterminent un droit ciblé de solidarité ; aucune déclaration redondante n’est prescrite ici. Les retirer sans dispositif de calcul coordonné ne serait pas une simple coupe administrative. L’avantage reste accessible aux prises en charge futures éligibles.",
"La liste inclut conjoint, concubin, partenaire de PACS, ascendants, descendants et collatéraux de chacun des membres du couple. Le taux d’incapacité est strictement supérieur au seuil réglementaire dans la source, à ne pas convertir en « au moins ». Note source : périodes à partir du 1er février 2014, malgré valid_from au 22 janvier 2014. L’attribut d’alignement de la source n’est pas un contenu normatif et aucune nouvelle proposition HTML n’est nécessaire.",
"Le mécanisme favorable de majoration est maintenu entier, sans nouvelle condition et sans prétendre abaisser les cotisations des aidants.",
"La mesure vise les proches et périodes énumérés ; aucune extension à tous les aidants ni financement supplémentaire de la capitalisation n’est décidée ici.")

